package shape

import "strings"

func repairCarriedDecisionDraft(draft string, problems []string) string {
 start := strings.Index(draft, "## Decisions\n")
 if start < 0 { return draft }
 start += len("## Decisions\n")
 end := len(draft)
 if n := strings.Index(draft[start:], "\n## "); n >= 0 {end=start+n}
 section := draft[start:end]
 var additions []string
 for _, p := range problems {
  _, line, ok := strings.Cut(p, "; keep it as: ")
  if !ok {continue}
  present := false
  for _, existing := range strings.Split(section, "\n") {if existing==line {present=true}}
  for _, existing := range additions {if existing==line {present=true}}
  if !present {additions=append(additions,line)}
 }
 if len(additions)==0 {return draft}
 body := strings.TrimRight(section, "\n")
 suffix := section[len(body):]
 return draft[:start]+body+"\n"+strings.Join(additions,"\n")+suffix+draft[end:]
}

package shape

import "strings"

func repairCarriedDecisionDraft(draft string, problems []string) string {
 var lines []string
 for _, p := range problems {if _, l, ok := strings.Cut(p, "; keep it as: "); ok {lines=append(lines,l)}}
 return strings.Replace(draft, "\n\n## Tests", "\n"+strings.Join(lines,"\n")+"\n\n## Tests", 1)
}
